<?php
require_once(__DIR__ . '/../../init.php'); class map_common_whatsNew extends common_main { const ERROR_INVALID_USER = -1; protected $db; protected $user; public function getLastWhatsNewVersion() { $db = $this->db ?: $this->db = connectDb(); $sql = <<<'EOT'
            SELECT COALESCE(U.VersionWhatsNewWeb, '') "versionWhatsNewWeb"
            FROM Users U
            WHERE UserCode = ?
EOT;
$stmt = $db->prepare($sql); $stmt->execute([$this->user]); $row = $stmt->fetch(); return $row['versionWhatsNewWeb']; } public function setLastWhatsNewVersion($version) { $db = $this->db ?: $this->db = connectDb(); $sql = <<<'EOT'
            UPDATE Users SET
                VersionWhatsNewWeb = ?
            WHERE UserCode = ?
EOT;
$stmt = $db->prepare($sql); $db->beginTransaction(); try { $stmt->execute([ $version, $this->user ]); $db->commit(); } catch (Throwable $e) { $db->rollback(); throw $e; } return true; } public function getChangelogList($params) { $this->user = isEmptyProperty($params, 'user'); $lastVersion = isEmptyProperty($params, 'version'); $commonMain = new map_common_main(); $tasks = $commonMain->readTasks(); $changelogDir = getServerRootPath() . 'help/changes/'; if (!is_dir($changelogDir)) { return json_encode(['success' => false, 'message' => 'Директория changes не найдена']); } $files = glob($changelogDir . '*.xml'); if (empty($files)) { return json_encode(['success' => false, 'message' => 'Нет информации об обновлениях']); } $changelogs = []; $lastKnownVersion = $this->getLastWhatsNewVersion(); $currentVersion = $lastVersion->server; $taskCodes = array_column($tasks, 'taskCode'); foreach ($files as $file) { if (pathinfo($file, PATHINFO_EXTENSION) === 'xml') { $xml = simplexml_load_file($file); $itemsHtml = ''; $items = []; foreach ($xml->item as $item) { $task = (string)$item['task']; $taskNums = explode(',', $task); $itemText = trim((string)$item, " \n\r\t<br>"); $itemsStr = []; $itemTitle = []; foreach ($taskNums as $num) { $key = array_search($num, $taskCodes); if ($key !== false) { $itemsStr[] = $num; $itemTitle[] = $tasks[$key]['taskName']; } } $ids = implode(',', $itemsStr); if ($ids) { $items[$ids][] = ['item' => $itemText, 'title' => implode(', ', $itemTitle)]; } } foreach ($items as $taskId => $itemArr) { if (!empty($itemArr)) { $itemsHtml .= '<div class="map-common-whatsnew paragraph">' . sprintf('<div class="p-h">%s</div>', $itemArr[0]['title']); foreach ($itemArr as $k => $v) { $itemsHtml .= sprintf('<div class="map-common-whatsnew list">%s</div>', nl2br($v['item'])); } $itemsHtml .= '</div>'; } } $isNewest = (version_compare((string)$xml['version'], $currentVersion) === 0); $isNewerThanLastKnown = version_compare((string)$xml['version'], $lastKnownVersion) > 0; $hasUpdates = version_compare($currentVersion, $lastKnownVersion) > 0; if (!empty($itemsHtml)) { $changelogs[] = [ 'version' => (string)$xml['version'], 'release' => (string)$xml['release'], 'items' => $itemsHtml, 'expanded' => $isNewest || ($isNewerThanLastKnown && $hasUpdates), 'collapsible' => !$isNewest ]; } } } if (!empty($changelogs)) { usort($changelogs, function ($a, $b) { return version_compare($b['version'], $a['version']); }); $this->setLastWhatsNewVersion($currentVersion); return json_encode($changelogs); } else { return json_encode(['success' => false, 'message' => 'Нет информации об обновлениях для пользователя']); } } } handleJsonRpc('map_common_whatsNew');